INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103011, ARRAY['"In the sentence “The technician repaired the computer,” which word is the verb?"'::jsonb, '"Which word is an adjective in “The careful student checked the result”?"'::jsonb, '"Which word is a pronoun?"'::jsonb, '"Which sentence is interrogative?"'::jsonb, '"Which sentence is imperative?"'::jsonb, '"Choose the correct simple-present form: “She ___ to college by bus.”"'::jsonb, '"Choose the correct past tense: “Yesterday, we ___ the museum.”"'::jsonb, '"Which sentence has correct subject–verb agreement?"'::jsonb, '"Choose the suitable modal for ability: “When he was six, he ___ swim.”"'::jsonb, '"Which is the passive form of “The clerk filed the report”?"'::jsonb]::jsonb[], ARRAY['"repaired"'::jsonb, '"computer"'::jsonb, '"the"'::jsonb, '"technician"'::jsonb, '"result"'::jsonb, '"careful"'::jsonb, '"student"'::jsonb, '"checked"'::jsonb, '"quickly"'::jsonb, '"bright"'::jsonb, '"they"'::jsonb, '"under"'::jsonb, '"Please close the window."'::jsonb, '"What a useful book!"'::jsonb, '"The lab opens at nine."'::jsonb, '"What time does the lab open?"'::jsonb, '"What a difficult task!"'::jsonb, '"Submit the assignment by Friday."'::jsonb, '"Where is the key?"'::jsonb, '"The assignment is ready."'::jsonb, '"go"'::jsonb, '"going"'::jsonb, '"gone"'::jsonb, '"goes"'::jsonb, '"visited"'::jsonb, '"visits"'::jsonb, '"visiting"'::jsonb, '"visit"'::jsonb, '"The list of items be ready."'::jsonb, '"The list of items are ready."'::jsonb, '"The list of items is ready."'::jsonb, '"The list of items were ready."'::jsonb, '"must"'::jsonb, '"should"'::jsonb, '"may"'::jsonb, '"could"'::jsonb, '"The clerk was filed by the report."'::jsonb, '"The report was filed by the clerk."'::jsonb, '"The report has filing the clerk."'::jsonb, '"The report files the clerk."'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

