INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103013, ARRAY['"Which reading technique is used to locate a date in a long report quickly?"'::jsonb, '"Which technique is most useful for getting the main idea of an article quickly?"'::jsonb, '"What is the main purpose of a topic sentence in a paragraph?"'::jsonb, '"Which source is usually best for a detailed definition of a technical term?"'::jsonb, '"Which text type normally records the sequence, outcomes and relevant details of an event?"'::jsonb, '"Which document is most appropriate to request official permission for leave from a college?"'::jsonb, '"Which opening is most suitable for a formal email to a faculty member whose name is known?"'::jsonb, '"Which detail most helps a reader understand an email''s purpose before opening it?"'::jsonb, '"Which greeting is suitable when introducing yourself in a formal presentation?"'::jsonb, '"Which presentation behaviour usually supports audience understanding?"'::jsonb]::jsonb[], ARRAY['"Skimming"'::jsonb, '"Memorising"'::jsonb, '"Scanning"'::jsonb, '"Proofreading only"'::jsonb, '"Reading only the last word of each line"'::jsonb, '"Copying the first paragraph"'::jsonb, '"Scanning every number"'::jsonb, '"Skimming headings and opening lines"'::jsonb, '"To state the paragraph''s central idea"'::jsonb, '"To provide only the final conclusion"'::jsonb, '"To list every reference"'::jsonb, '"To replace punctuation"'::jsonb, '"A random comment thread"'::jsonb, '"A relevant reference book or trusted technical source"'::jsonb, '"An unrelated advertisement"'::jsonb, '"A photograph with no caption"'::jsonb, '"Dictionary entry"'::jsonb, '"Advertisement slogan"'::jsonb, '"Recipe only"'::jsonb, '"Event report"'::jsonb, '"A product review"'::jsonb, '"A formal application"'::jsonb, '"A social-media caption"'::jsonb, '"An informal chat full of abbreviations"'::jsonb, '"Hey dude,"'::jsonb, '"Yo!"'::jsonb, '"Dear Professor Patel,"'::jsonb, '"What''s up!!!"'::jsonb, '"A clear subject line"'::jsonb, '"An empty subject"'::jsonb, '"A long signature alone"'::jsonb, '"Several unrelated attachments"'::jsonb, '"“Listen up, everyone!”"'::jsonb, '"“Hi, I am [name], from [department].”"'::jsonb, '"“You all know me, so no introduction.”"'::jsonb, '"“I have no idea why I am here.”"'::jsonb, '"Speaking while facing the screen throughout"'::jsonb, '"Reading every slide word for word"'::jsonb, '"Turning away during every key point"'::jsonb, '"Using clear speech and looking at the audience periodically"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

