VALUES (440919120103014, ARRAY['"Which sentence has correct punctuation?"'::jsonb, '"Choose the correct plural: “The ___ are in the laboratory.”"'::jsonb, '"Choose the correct comparative: “This explanation is ___ than the previous one.”"'::jsonb, '"Choose the correct word: “Please ___ the report before sending it.”"'::jsonb, '"Which sentence has the clearest pronoun reference?"'::jsonb, '"Which phrase is most appropriate in a formal application?"'::jsonb, '"Which section usually contains the subject and purpose of a formal email?"'::jsonb, '"What should a concise event report generally include?"'::jsonb, '"Which is the best response when an audience member asks a question you do not know how to answer?"'::jsonb, '"Which pronunciation practice is most useful for a technical presentation?"'::jsonb]::jsonb[], ARRAY['"Lets'' begin the meeting."'::jsonb, '"Lets begin, the meeting."'::jsonb, '"Lets begin the meeting."'::jsonb, '"Let''s begin the meeting."'::jsonb, '"equipment"'::jsonb, '"equipment''s"'::jsonb, '"equipments"'::jsonb, '"piece of equipment"'::jsonb, '"clear"'::jsonb, '"clearer"'::jsonb, '"clearest"'::jsonb, '"more clearer"'::jsonb, '"reviewing"'::jsonb, '"reviewed"'::jsonb, '"review"'::jsonb, '"reviews"'::jsonb, '"Rina submitted the file after Rina checked the figures."'::jsonb, '"After speaking to Meera, she left."'::jsonb, '"When Rina met Meera, she was late."'::jsonb, '"The student told the teacher that they were wrong."'::jsonb, '"I wanna take leave."'::jsonb, '"Give me off, please."'::jsonb, '"I request leave for two days due to illness."'::jsonb, '"Can''t come, so bye."'::jsonb, '"Only the attachment filename"'::jsonb, '"The final punctuation mark"'::jsonb, '"A random line in the signature"'::jsonb, '"Subject line and opening sentence"'::jsonb, '"An unrelated biography"'::jsonb, '"Relevant date, venue, activities and outcomes"'::jsonb, '"Only personal opinions"'::jsonb, '"Only the writer''s favourite moment"'::jsonb, '"Invent a confident answer"'::jsonb, '"Ignore the person"'::jsonb, '"Acknowledge the question and offer to verify the information"'::jsonb, '"End the presentation immediately"'::jsonb, '"Practise key terms aloud and check unfamiliar pronunciations"'::jsonb, '"Avoid all pauses"'::jsonb, '"Read silently only"'::jsonb, '"Speak faster whenever a term is unfamiliar"'::jsonb]::jsonb[], ARRAY['3'::jsonb, '0'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103015, ARRAY['"Choose the correct verb: “Each of the laboratory computers ___ a separate asset number.”"'::jsonb, '"Choose the correct tense: “By the time the instructor arrived, the students ___ the setup.”"'::jsonb, '"Choose the correct modal: “You ___ save a backup before changing the system files.”"'::jsonb, '"Choose the correct passive sentence for “The staff will publish the timetable tomorrow.”"'::jsonb, '"Choose the correct reported form: He said, “I am ready.”"'::jsonb, '"Select the sentence with correct subject–verb agreement."'::jsonb, '"Choose the correct relative pronoun: “The technician ___ repaired the monitor is here.”"'::jsonb, '"Choose the sentence that expresses a condition correctly."'::jsonb, '"Which sentence avoids a dangling modifier?"'::jsonb, '"Choose the correct form: “The list of participants, along with the instructor, ___ on the desk.”"'::jsonb]::jsonb[], ARRAY['"has"'::jsonb, '"were have"'::jsonb, '"have"'::jsonb, '"are having"'::jsonb, '"complete"'::jsonb, '"had completed"'::jsonb, '"completed"'::jsonb, '"will complete"'::jsonb, '"can to"'::jsonb, '"would to"'::jsonb, '"ought to"'::jsonb, '"might not have"'::jsonb, '"The timetable has publish tomorrow."'::jsonb, '"The timetable is publish tomorrow."'::jsonb, '"The staff will be published the timetable."'::jsonb, '"The timetable will be published tomorrow."'::jsonb, '"He said that I am ready."'::jsonb, '"He said that he was ready."'::jsonb, '"He said that he ready."'::jsonb, '"He says that he were ready."'::jsonb, '"The quality of these components have high."'::jsonb, '"The quality of these components were high."'::jsonb, '"The quality of these components are high."'::jsonb, '"The quality of these components is high."'::jsonb, '"who"'::jsonb, '"whose only"'::jsonb, '"which"'::jsonb, '"where"'::jsonb, '"If the file will save, we can closed it."'::jsonb, '"If saved the file, we can closing."'::jsonb, '"If the file is saved, we can close the program."'::jsonb, '"If the file saved, we can closes."'::jsonb, '"Walking into the lab, the bright lights were noticed."'::jsonb, '"The lights, walking into the lab, looked bright."'::jsonb, '"Walking into the lab, the lights looked bright."'::jsonb, '"Walking into the lab, I noticed the bright lights."'::jsonb, '"have"'::jsonb, '"is"'::jsonb, '"are"'::jsonb, '"were"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103016, ARRAY['"A passage says the lab stayed open until 6 p.m., although the posted schedule said 5 p.m. Which conclusion is directly supported?"'::jsonb, '"A report states, “The number of visitors rose from 120 to 150.” What was the numerical increase?"'::jsonb, '"An article presents a claim and then gives two examples. What is the best reading approach to evaluate whether the examples support the claim?"'::jsonb, '"An email asks for a reply by 4 p.m. and includes three optional background links. Which detail should the recipient note first to act appropriately?"'::jsonb, '"Which subject line best fits an email requesting approval for an industrial visit on 12 November?"'::jsonb, '"Which sentence is most appropriate in a formal request email?"'::jsonb, '"An event report must distinguish facts from opinion. Which entry is a verifiable fact?"'::jsonb, '"A student must present three reasons supporting a recommendation. Which structure is clearest?"'::jsonb, '"A listener asks for clarification during a presentation. What is the most effective response?"'::jsonb, '"A presenter uses highly technical terms with a mixed audience. What is the strongest adjustment?"'::jsonb]::jsonb[], ARRAY['"The lab always closes at 6 p.m."'::jsonb, '"On that occasion, the lab stayed open one hour beyond the posted time."'::jsonb, '"The schedule is permanently cancelled."'::jsonb, '"The lab was closed all day."'::jsonb, '"25"'::jsonb, '"35"'::jsonb, '"30"'::jsonb, '"20"'::jsonb, '"Assume every example proves the claim"'::jsonb, '"Copy the title without reading"'::jsonb, '"Count the number of paragraphs only"'::jsonb, '"Identify the claim and compare each example with it"'::jsonb, '"The deadline for replying"'::jsonb, '"The sender''s font choice"'::jsonb, '"The number of links only"'::jsonb, '"The length of the signature"'::jsonb, '"Urgent!!!"'::jsonb, '"Industrial visit, and also several unrelated matters"'::jsonb, '"Request for Approval: Industrial Visit on 12 November"'::jsonb, '"Hello"'::jsonb, '"I''d be grateful if you could approve the attached plan by Friday."'::jsonb, '"Approval or whatever is fine."'::jsonb, '"Send me the approval today."'::jsonb, '"You must do it because I said so."'::jsonb, '"The event was the best in college history."'::jsonb, '"The seminar began at 10 a.m. and had 85 registered attendees."'::jsonb, '"Everyone loved every speech."'::jsonb, '"The decorations were unquestionably perfect."'::jsonb, '"Put the conclusion first, omit reasons"'::jsonb, '"Use a single paragraph of run-on sentences"'::jsonb, '"List unrelated definitions and stop"'::jsonb, '"State the recommendation, give three ordered reasons with evidence, then conclude"'::jsonb, '"Pause, restate the point in simpler words, and check whether it is clear"'::jsonb, '"Tell the audience the question is irrelevant"'::jsonb, '"Repeat the same sentence more loudly without checking understanding"'::jsonb, '"Ignore the question until the end"'::jsonb, '"Keep every term unexplained"'::jsonb, '"Increase speaking speed"'::jsonb, '"Define essential terms briefly and use examples at the audience''s level"'::jsonb, '"Remove all examples"'::jsonb]::jsonb[], ARRAY['1'::jsonb, '2'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103017, ARRAY['"Choose the sentence in which the modal expresses obligation rather than possibility."'::jsonb, '"Choose the correct verb form: “Neither the students nor the lab assistant ___ available.”"'::jsonb, '"Which revision corrects the passive voice error in “The instructions was printed yesterday”?"'::jsonb, '"Select the sentence with correct parallel structure."'::jsonb, '"A passage states that a new bus route cut a journey from 50 minutes to 35 minutes. What is the decrease in travel time?"'::jsonb, '"A passage says “Some students prefer printed notes, while others revise using digital files.” Which inference is strongest?"'::jsonb, '"An application needs a clear purpose and the dates requested. Which opening is best?"'::jsonb, '"Which revision improves clarity: “Due to the fact that the device overheated, therefore we stopped the test”?"'::jsonb, '"A speaker has only 90 seconds to explain a process with six steps. What should they do?"'::jsonb, '"Which statement is the strongest closing for a recommendation presentation?"'::jsonb]::jsonb[], ARRAY['"The upload could finish soon."'::jsonb, '"The file might be corrupted."'::jsonb, '"Users must log out before maintenance."'::jsonb, '"The server may restart tonight."'::jsonb, '"have"'::jsonb, '"are"'::jsonb, '"were"'::jsonb, '"is"'::jsonb, '"The instructions were printed yesterday."'::jsonb, '"The instructions was print yesterday."'::jsonb, '"The instructions are printed yesterday by them."'::jsonb, '"The instruction were printing yesterday."'::jsonb, '"The role requires to plan, testing and documentation."'::jsonb, '"The role requires planning, testing and documenting results."'::jsonb, '"The role requires planning, to test and documentation results."'::jsonb, '"The role requires planning, testing and to document results."'::jsonb, '"25 minutes"'::jsonb, '"10 minutes"'::jsonb, '"20 minutes"'::jsonb, '"15 minutes"'::jsonb, '"All students dislike digital files."'::jsonb, '"Students may use different revision preferences."'::jsonb, '"Digital files cannot contain notes."'::jsonb, '"Printed notes always produce better marks."'::jsonb, '"Hey, I won''t be there."'::jsonb, '"You know why I am writing."'::jsonb, '"I request leave from 14 to 16 December because of a scheduled medical appointment."'::jsonb, '"This is about something I need."'::jsonb, '"Because the device overheated, we stopped the test."'::jsonb, '"Because of the reason that the test stopped."'::jsonb, '"Due to the device overheating, therefore the test was stopped by us."'::jsonb, '"The device overheated, because therefore we stopped."'::jsonb, '"Read every detail at maximum speed"'::jsonb, '"Group related steps, highlight key actions, and leave time for a brief summary"'::jsonb, '"Skip the objective and repeat the title"'::jsonb, '"Show a dense slide and remain silent"'::jsonb, '"My slides are finished."'::jsonb, '"The topic is complicated, so no decision is possible."'::jsonb, '"That is all, and I do not know what to add."'::jsonb, '"To conclude, the trial met the stated criteria; I recommend a monitored rollout and review after one month."'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103018, ARRAY['"Which revision is most concise and formal?"'::jsonb, '"A teammate writes an email to request missing attendance data. Which version is most actionable?"'::jsonb, '"An event report includes time, venue, agenda, attendance and outcomes, but omits the writer''s unsupported claim that the event was ''perfect''. What is the main benefit?"'::jsonb, '"A presentation slide contains eight sentences in small type. What change most likely improves readability without losing the key message?"'::jsonb, '"A presenter notices the audience looking confused after a technical definition. What is a useful immediate response?"'::jsonb, '"Which pair contains a common formal-email closing and a suitable use?"'::jsonb, '"A report describes a student event held yesterday. Which tense is best for completed activities?"'::jsonb, '"Which note-taking method best helps prepare a short summary from a longer article?"'::jsonb, '"The audience cannot hear the last row during a presentation. What should the speaker adjust first?"'::jsonb, '"During Q&A, a question has two parts. What response technique helps avoid missing one part?"'::jsonb]::jsonb[], ARRAY['"The request review, it is taking place."'::jsonb, '"At this point in time, we are currently reviewing the request."'::jsonb, '"We are doing a review of the request at the present time now."'::jsonb, '"We are reviewing the request."'::jsonb, '"Please send the attendance totals for 1–10 October by 3 p.m. Thursday so I can finish the report."'::jsonb, '"Send the data sometime."'::jsonb, '"Where is it?"'::jsonb, '"You forgot again!"'::jsonb, '"It removes all useful detail"'::jsonb, '"It prioritizes verifiable reporting over subjective praise"'::jsonb, '"It converts the report into an informal message"'::jsonb, '"It makes the report impossible to read"'::jsonb, '"Add multiple animations to every sentence"'::jsonb, '"Increase sentences to twelve"'::jsonb, '"Turn the content into a clear heading and a few concise points, then explain details orally"'::jsonb, '"Remove the heading and shrink the type"'::jsonb, '"Give a short example or analogy and invite a clarification question"'::jsonb, '"Proceed faster"'::jsonb, '"Blame the audience"'::jsonb, '"Repeat the definition word-for-word and move on"'::jsonb, '"“Whatever” — a request to the principal"'::jsonb, '"“Later!!!” — a report to a department head"'::jsonb, '"“Yours sincerely” — a formal message to a named recipient"'::jsonb, '"“See ya” — a formal job application"'::jsonb, '"Present continuous only"'::jsonb, '"Future perfect only"'::jsonb, '"Simple future"'::jsonb, '"Simple past"'::jsonb, '"Copy every sentence without selection"'::jsonb, '"Record the main claim and its most relevant supporting points"'::jsonb, '"Write only unfamiliar words"'::jsonb, '"Record page numbers but no ideas"'::jsonb, '"Speak faster"'::jsonb, '"Remove the microphone without checking"'::jsonb, '"Project the voice clearly toward the audience and check audibility"'::jsonb, '"Turn toward the screen and speak into it"'::jsonb, '"Briefly restate the two parts, answer each in turn, and check if anything remains"'::jsonb, '"Ask the audience to leave"'::jsonb, '"Answer only the easiest part"'::jsonb, '"Change to an unrelated slide"'::jsonb]::jsonb[], ARRAY['3'::jsonb, '0'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103019, ARRAY['"Choose the sentence that correctly combines a past event completed before another past event."'::jsonb, '"Which revision correctly removes the unclear pronoun reference? Original: “Asha spoke to Nita after she completed the test.”"'::jsonb, '"A technician''s instructions must describe four actions in the order performed. Which wording has the strongest procedural clarity?"'::jsonb, '"Choose the only grammatically correct sentence."'::jsonb, '"A passage says an equipment upgrade reduced average processing time from 80 seconds to 60 seconds. What percentage reduction is reported?"'::jsonb, '"A text states that the library expanded its hours in March after surveying users, but gives no attendance figures. Which statement is supported?"'::jsonb, '"A formal email asks for approval and must include an attachment, deadline and a respectful tone. Which draft is most complete?"'::jsonb, '"Which sentence preserves parallel construction in a project objective list?"'::jsonb, '"A presenter has evidence that a pilot worked with 12 participants. Which conclusion is best calibrated to the evidence?"'::jsonb, '"A reading question asks what cannot be concluded from a passage. Which approach is best?"'::jsonb]::jsonb[], ARRAY['"When the supervisor arrived, we had already saved the file."'::jsonb, '"When the supervisor had arrived, we already save the file."'::jsonb, '"When the supervisor arrives, we had saved the file."'::jsonb, '"When the supervisor arriving, we have saved the file."'::jsonb, '"Asha and Nita spoke after she did it."'::jsonb, '"Asha spoke to Nita after Asha completed the test."'::jsonb, '"She spoke to her after completing the test."'::jsonb, '"After she completed the test, Asha spoke to Nita."'::jsonb, '"Inspect and disconnect whenever convenient."'::jsonb, '"Disconnect power and inspect things, then do the rest."'::jsonb, '"First disconnect power, then remove the cover, inspect the cable, and reconnect power only after refitting the cover."'::jsonb, '"Reconnect power before removing the cover, unless it is not needed."'::jsonb, '"Each of the reports contain a summary."'::jsonb, '"Each reports contains summaries."'::jsonb, '"Each of the report contain summary."'::jsonb, '"Each of the reports contains a summary."'::jsonb, '"30%"'::jsonb, '"25%"'::jsonb, '"33⅓%"'::jsonb, '"20%"'::jsonb, '"The library has always been open longer in March."'::jsonb, '"Attendance definitely increased."'::jsonb, '"The survey proves every user supported the change."'::jsonb, '"The library expanded hours after a user survey."'::jsonb, '"Please approve the attached visit plan by Friday; let me know if any additional information is required."'::jsonb, '"Approve it."'::jsonb, '"Attached. Need it now!!!"'::jsonb, '"I am sending something, so please decide."'::jsonb, '"The project aims at reducing delays, accuracy improved and errors."'::jsonb, '"The project aims to reduce delays, accuracy and to be fewer errors."'::jsonb, '"The project aims to reduce delays, improve accuracy and reduce errors."'::jsonb, '"The project aims to reduce delays, improving accuracy and fewer errors."'::jsonb, '"The results are invalid because the group is not enormous."'::jsonb, '"The method will succeed for every department."'::jsonb, '"The pilot proves no further testing is useful."'::jsonb, '"The pilot suggests the method may help in similar settings, but a larger trial is needed."'::jsonb, '"Choose a statement that sounds familiar even if the passage is silent"'::jsonb, '"Distinguish explicit facts and justified inferences from claims with no textual support"'::jsonb, '"Use the longest option"'::jsonb, '"Assume a real-world fact must be mentioned in the passage"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4409191201030110, ARRAY['"Choose the best revision: “After reviewing the data, the conclusion was changed by the analyst because it was incomplete.”"'::jsonb, '"A report has evidence, a conclusion and a recommendation, but the conclusion repeats the opening word-for-word. What revision most improves its function?"'::jsonb, '"A passage says the company received 300 applications and interviewed 45 candidates. What proportion of applicants were interviewed?"'::jsonb, '"A passage describes a trial at one campus and says the approach ''may be useful elsewhere''. Which interpretation respects the wording?"'::jsonb, '"Which option best combines the two sentences without changing their meaning? “The server was unavailable. The team postponed the demo.”"'::jsonb, '"A student must prepare a 3-minute presentation from a long technical report for non-specialists. Which workflow is most effective?"'::jsonb, '"A formal application contains long background paragraphs but never states the requested action. What is the critical repair?"'::jsonb, '"An audience asks a challenging question that questions one slide''s statistics. What should the presenter do first?"'::jsonb, '"A text contains a fact, an author''s opinion and an inference. Which labeling method is sound?"'::jsonb, '"A report must present events chronologically and explain the outcome. Which structure is clearest?"'::jsonb]::jsonb[], ARRAY['"The data was reviewing, so the conclusion changed it."'::jsonb, '"After reviewing the data, the analyst changed the conclusion because the earlier analysis was incomplete."'::jsonb, '"The analyst, after data, changed because incomplete."'::jsonb, '"After reviewing the data, the conclusion reviewed the analyst."'::jsonb, '"Repeat every paragraph verbatim"'::jsonb, '"Remove all evidence"'::jsonb, '"Use the conclusion to synthesize the findings and lead logically to the recommendation"'::jsonb, '"Add unrelated background facts"'::jsonb, '"10%"'::jsonb, '"20%"'::jsonb, '"25%"'::jsonb, '"15%"'::jsonb, '"The text expresses a possibility, not a universal conclusion."'::jsonb, '"The trial happened at every campus."'::jsonb, '"The wording proves the approach failed."'::jsonb, '"The approach is proven effective at every campus."'::jsonb, '"The server was unavailable, the team and demo."'::jsonb, '"The server was unavailable, although the demo was postponed because it worked."'::jsonb, '"Because the server was unavailable, the team postponed the demo."'::jsonb, '"The team postponed the demo unless the server was unavailable."'::jsonb, '"Identify one purpose, select essential findings, define key terms, use a simple visual and rehearse to time"'::jsonb, '"Copy the abstract and read it aloud unchanged"'::jsonb, '"Use every table and footnote"'::jsonb, '"Start from the final appendix and add no context"'::jsonb, '"Make every sentence passive"'::jsonb, '"Add a clear request and relevant dates near the beginning"'::jsonb, '"Move the request to a hidden footnote"'::jsonb, '"Add more adjectives"'::jsonb, '"Switch topics without replying"'::jsonb, '"Dismiss the question as irrelevant"'::jsonb, '"Invent a larger sample size"'::jsonb, '"Acknowledge the concern, identify the figure/source and clarify what it does and does not show"'::jsonb, '"Mark verifiable statements as facts, evaluative claims as opinions and reasoned but unstated conclusions as inferences"'::jsonb, '"Treat all three as equally explicit facts"'::jsonb, '"Label the longest statement as fact"'::jsonb, '"Classify any sentence with a number as opinion"'::jsonb, '"Only personal reaction"'::jsonb, '"A list of adjectives followed by the title"'::jsonb, '"Background/purpose, chronological activities, outcomes and concise conclusion"'::jsonb, '"Outcome first, random anecdotes and no dates"'::jsonb]::jsonb[], ARRAY['1'::jsonb, '2'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4409191201030111, ARRAY['"A formal email asks a faculty member to review a project proposal and needs to mention an attached file. Which subject and opening are strongest?"'::jsonb, '"A report gives this data: attendance was 90, 105 and 120 over three successive sessions. Which statement is precise and avoids overclaiming?"'::jsonb, '"An application requests leave from 8 to 10 January. Which detail is essential to make the request actionable?"'::jsonb, '"A slide says “The new process is faster” and lists times of 14 minutes before and 9 minutes after. Which rewrite best combines claim and evidence?"'::jsonb, '"The audience includes beginners and experienced technicians. How should the speaker handle essential technical vocabulary?"'::jsonb, '"A speaker loses their place after an audience question. Which preparation method best prevents the interruption from derailing the talk?"'::jsonb, '"A student reports “Everyone agreed that the workshop was useful,” but only 4 of 20 respondents completed the feedback form. What is the best correction?"'::jsonb, '"An email contains a vague subject, an attachment with an unclear filename, and a deadline only in the final paragraph. Which revision most improves usability?"'::jsonb, '"A speaker is challenged about a statistic but is unsure of the source. What is the most credible response?"'::jsonb, '"A reading passage gives one example of a benefit but does not discuss cost. Which conclusion about cost is safest?"'::jsonb]::jsonb[], ARRAY['"Subject: Proposal; no greeting, no request, no deadline"'::jsonb, '"Subject: Read this!!!; Hey, open it now."'::jsonb, '"Subject: Review Request — Project Proposal; Dear Professor, could you review the attached proposal by Thursday?"'::jsonb, '"Subject: hi; I sent a thing."'::jsonb, '"Every future session will increase by 15."'::jsonb, '"The program doubled attendance."'::jsonb, '"Attendance was unchanged."'::jsonb, '"Attendance increased by 15 at each successive session in the recorded data."'::jsonb, '"A clear reason and dates, plus a request for approval"'::jsonb, '"Only a greeting"'::jsonb, '"An anonymous statement without dates"'::jsonb, '"A long description of unrelated hobbies"'::jsonb, '"The process is the fastest in the world."'::jsonb, '"Recorded completion time fell from 14 to 9 minutes, a 5-minute reduction."'::jsonb, '"The process is faster because it is good."'::jsonb, '"The team always works faster now."'::jsonb, '"Use unexplained abbreviations throughout"'::jsonb, '"Avoid all technical terms even when needed"'::jsonb, '"Use a different synonym every time"'::jsonb, '"Define each important term briefly, then use the same term consistently"'::jsonb, '"Remove all headings from slides"'::jsonb, '"Use a clear outline with signposts and keep brief cue notes for the next section"'::jsonb, '"End the session as soon as someone asks a question"'::jsonb, '"Memorize every word and never use notes"'::jsonb, '"The response rate proves the event failed."'::jsonb, '"All participants found the workshop useful."'::jsonb, '"Four respondents submitted feedback; conclusions about all attendees cannot be drawn from those responses alone."'::jsonb, '"No one found it useful."'::jsonb, '"Use a specific subject, a descriptive filename and an early, explicit deadline"'::jsonb, '"Make the email longer without changing organization"'::jsonb, '"Remove the deadline"'::jsonb, '"Attach multiple duplicate files"'::jsonb, '"Insist the number must be right"'::jsonb, '"State that you cannot verify the source immediately and offer to follow up with a checked reference"'::jsonb, '"Ignore the question and change the slide"'::jsonb, '"Invent a source on the spot"'::jsonb, '"The benefit proves cost is irrelevant"'::jsonb, '"The approach is inexpensive"'::jsonb, '"The approach is expensive"'::jsonb, '"The passage does not establish the cost"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4409191201030112, ARRAY['"A presentation must recommend a network upgrade. Test data shows failures dropped from 12 to 3 in a pilot of 10 devices, but the sample is small. Which closing is best?"'::jsonb, '"A report draft includes an unsupported cause for a rise in attendance. The records show attendance rose, but no reasons were collected. What should the writer do?"'::jsonb, '"An email requests an urgent document, but the recipient''s role is unclear and the deadline is unrealistic. What is the best communication strategy?"'::jsonb, '"During Q&A, two audience members ask conflicting questions about whether a trial is complete. The report says testing finished but monitoring continues. What is the accurate response?"'::jsonb, '"A student has to summarize a four-page passage in 80 words and keep the main claim and two key findings. Which technique is most suitable?"'::jsonb, '"A recommendation is supported by three measurements, but one was collected under different conditions. How should it be presented?"'::jsonb, '"A speaker notices that a translated technical term confuses the audience. Which response best supports comprehension and accuracy?"'::jsonb, '"A formal report describes an event held on 4 September but uses present tense for most completed activities. What is the best editing principle?"'::jsonb, '"A presenter wants to persuade an audience while remaining evidence-based. Which approach is strongest?"'::jsonb, '"A text indicates that a college is considering a new timetable but has not approved it. Which statement is justified?"'::jsonb]::jsonb[], ARRAY['"The upgrade eliminates all failures everywhere."'::jsonb, '"No decision can ever be made."'::jsonb, '"The data is irrelevant because ten devices were used."'::jsonb, '"The pilot showed fewer failures, so a larger controlled rollout is recommended before broad deployment."'::jsonb, '"Report the increase and note that the available data does not establish its cause"'::jsonb, '"Delete the attendance figures"'::jsonb, '"Claim that every participant gave the same reason"'::jsonb, '"State the cause as fact because the rise is visible"'::jsonb, '"Remove the subject line"'::jsonb, '"Clarify the required document, explain the reason for the deadline and propose a feasible time if needed"'::jsonb, '"Send an angry reminder"'::jsonb, '"Copy every person in the organization immediately"'::jsonb, '"The project is permanently finished in every respect."'::jsonb, '"No work has been completed."'::jsonb, '"The planned testing phase is complete, while post-test monitoring is still ongoing."'::jsonb, '"The report contains no distinction between testing and monitoring."'::jsonb, '"Identify the thesis, select two findings, remove examples and repetition, then check the word count"'::jsonb, '"Retain all minor details and reduce font size"'::jsonb, '"Write a personal response instead of a summary"'::jsonb, '"Copy the first 80 words"'::jsonb, '"Pick whichever number supports the preferred conclusion"'::jsonb, '"Combine all measurements as directly comparable without qualification"'::jsonb, '"Report the comparable measurements and explain the differing condition before using the third value"'::jsonb, '"Delete the methods from the report"'::jsonb, '"Repeat it louder in the same unfamiliar wording"'::jsonb, '"Replace the term with an unrelated word"'::jsonb, '"Avoid answering further questions"'::jsonb, '"Give the accepted term, explain it in plain language and provide a relevant example"'::jsonb, '"Remove all verbs"'::jsonb, '"Use consistent past tense for completed events while retaining present tense for current conclusions or general facts"'::jsonb, '"Use a different tense in every paragraph"'::jsonb, '"Change every verb to future tense"'::jsonb, '"Add unrelated statistics"'::jsonb, '"Use confident language instead of evidence"'::jsonb, '"State a recommendation, show relevant evidence and limits, address a likely objection, then give a specific next step"'::jsonb, '"Hide limitations"'::jsonb, '"The college is considering the timetable, but approval is not yet established."'::jsonb, '"The timetable has been implemented."'::jsonb, '"The timetable will definitely be used."'::jsonb, '"The timetable has been rejected."'::jsonb]::jsonb[], ARRAY['3'::jsonb, '0'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb]::jsonb[]);
COMMIT;
